	DEPOSIT_RECEIPT_TM TIME(9) NOT NULL COMMENT 'The day represented as a calendar_1 date of the form YYYY-MM_1-DD. YYYY is the calendar_1 year, MM_1 (between 1 and 12) the calendar_1 month and DD the day of the calendar_1 month (between 1 and 31). ',
	DEPOSIT_RECEIPT_NR NUMBER(38,0) NOT NULL COMMENT 'The deposit receipt number generated by the rvm.',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a main store. It is identical to the key of the store that has first been assigned to this main store.',
	CASH_RECEIPT_NR NUMBER(38,0) COMMENT 'The unique identifier for a receipt generated by the cash',
