	CASH_RECEIPT_TM TIME(9) COMMENT 'The day represented as a calendar_1 date of the form YYYY-MM_1-DD. YYYY is the calendar_1 year, MM_1 (between 1 and 12) the calendar_1 month and DD the day of the calendar_1 month (between 1 and 31). ',
	OUTPAYMENT_STORE_NR VARCHAR(250) COMMENT 'The number by which the store is known to business. This number is unique for a given client_id, but not globally unique. (The same number can be in different clients).',
	DEPOSIT_OUTPAYMENT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The code for the way how the deposit amount can be paid back to the customer. (outpayment / donation / QR code / ...',
	LOCAL_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217. - Local Currency of the country_1',
	DEPOSIT_LOCAL_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The deposit value from a deposit receipt in euro',
	GLOBAL_CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217. - Global Currency (EUR)',
	DEPOSIT_GLOBAL_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The deposit value from a deposit receipt in national currency',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)',
	constraint PK_T_FACT_DEPOSIT_CASH_DATA_DEPOSIT_RECEIPT_REL primary key (RVM_SID, DEPOSIT_RECEIPT_DT, DEPOSIT_RECEIPT_TM, DEPOSIT_RECEIPT_NR, STORE_SID)
)COMMENT='Transactional Facts - Bridge table - Relational data connecting transactional deposit receipt data and deposit cash data on a common aggregation level. Foreign Key attributes from cash data are mapped to deposit receipt data, which can result in possible NULL values. Reason: not every '
;